on conflict (template_key, profile_key) do update set label = excluded.label, party_kinds = excluded.party_kinds,
  name_hints = excluded.name_hints, default_gl = excluded.default_gl, ask = excluded.ask, split_lines = excluded.split_lines,
  line_rules = excluded.line_rules, notes = excluded.notes, updated_at = now();

-- every profile's codes must exist in the template chart
do $$ declare bad text; begin
  select string_agg(distinct x.code, ', ') into bad from (
    select profile_key, default_gl code from phg.gl_coding_profiles where template_key = 'bar_restaurant_standard' and default_gl is not null
    union all
    select profile_key, r->>'gl_code' from phg.gl_coding_profiles, jsonb_array_elements(line_rules) r where template_key = 'bar_restaurant_standard'
  ) x where not exists (select 1 from phg.gl_accounts g where g.account_id is null and g.template_key = 'bar_restaurant_standard' and g.code = x.code);
  if bad is not null then raise exception '04a: profile codes missing from the chart: %', bad; end if;
end $$;
